inline uint8_t unicodeFlags(uint32_t cp) {
  size_t l = 0, r = std::size(unicode_ranges);
  while (l < r) {
    auto m = (l + r) / 2;
    if (unicode_ranges[m].last < cp)
      l = m + 1;
    else
      r = m;
  }
  return l < std::size(unicode_ranges) && unicode_ranges[l].first <= cp ? unicode_ranges[l].flags : 0;
}
